class Expense:
    def __init__(self, title, amount, category):
        self.title = title
        self.amount = amount
        self.category = category

class Tracker:
    def __init__(self):
        self.items = []

    def add(self, title, amount, category):
        self.items.append(Expense(title, amount, category))

    def total(self):
        return sum(e.amount for e in self.items)

    def by_category(self):
        totals = {}
        for e in self.items:
            totals[e.category] = totals.get(e.category, 0) + e.amount
        return totals

    def biggest(self):
        return max(self.items, key=lambda e: e.amount)

tracker = Tracker()
tracker.add("Groceries", 54.20, "Food")
tracker.add("Bus pass", 30.00, "Transport")
tracker.add("Lunch", 12.50, "Food")
tracker.add("Book", 18.99, "Learning")

print(f"Total spent: {tracker.total():.2f}")
for category, amount in tracker.by_category().items():
    print(f"{category}: {amount:.2f}")
big = tracker.biggest()
print(f"Biggest expense: {big.title} ({big.amount:.2f})")

