import json

tasks = []

def add_task(title):
    tasks.append({"title": title, "done": False})
    print("Added:", title)

def show_tasks():
    if not tasks:
        print("No tasks yet.")
        return
    for i, task in enumerate(tasks, 1):
        mark = "x" if task["done"] else " "
        print(f"{i}. [{mark}] {task['title']}")

def complete_task(number):
    if 1 <= number <= len(tasks):
        tasks[number - 1]["done"] = True
        print("Completed task", number)
    else:
        print("No task with that number")

while True:
    command = input("> ").strip()
    if command == "quit":
        break
    elif command.startswith("add "):
        add_task(command[4:])
    elif command.startswith("done "):
        complete_task(int(command[5:]))
    elif command == "list":
        show_tasks()
    elif command == "save":
        print(json.dumps(tasks))
    else:
        print("Commands: add <text>, done <n>, list, save, quit")

